const BASE=0x08000000,h=n=>'0x'+Number(n).toString(16).toUpperCase();
export function nativeStoryWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc,state={active:false,mapKey:null,rootId:null,limit:100,view:'scene'},host=document.createElement('section');host.id='nativeStoryWorkspace';host.className='story-workspace';host.hidden=true;document.querySelector('#app').append(host);
 const systems=shatteredSystemsWorkshop({...api,afterChange:()=>draw()});
 const session=()=>api.session(),graph=()=>api.project().nativeStory?.[session()?.id];let drag=null,cam={x:25,y:25,scale:.8};
 function close(){state.active=false;host.hidden=true;api.leave();}
 function projectCards(){state.active=false;host.hidden=true;api.projectCards();}
 async function importEvents(all=true){const s=session(),p=api.project();if(!s){api.pickROM('maps');return;}api.modal('Import ROM event graph','<p id="nativeStoryProgress">Reading NPC, sign, trigger and map-entry scripts…</p>');const node=$('#nativeStoryProgress'),active=()=>session()===s&&api.project()===p&&node?.isConnected&&$('#dialog').open;try{const next=await indexNativeStory(s.reader,{mapKeys:all?null:p.maps.filter(m=>m.rom?.sourceId===s.id).map(m=>m.rom.key),previous:graph(),shouldContinue:active,progress:(n,left)=>{if(active())node.textContent=n+' commands read · '+left+' branches queued';}});if(!active())return;api.change(()=>{p.nativeStory??={};p.nativeStory[s.id]=next;});api.close();open();}catch(e){if(e.name!=='AbortError')api.error(e);}}
 function open(){if(!session()){api.modal('ROM story','<p>Open the matching source ROM to discover its native events.</p><button id="nativeStoryChooseROM" type="button">Open ROM</button>');$('#nativeStoryChooseROM').onclick=()=>api.pickROM('maps');return;}if(state.sourceId!==session().id){state.sourceId=session().id;state.mapKey=api.project().maps.find(m=>m.id===api.project().activeMapId)?.rom?.key??null;state.rootId=null;}state.active=true;host.hidden=false;draw();}
 function draw(){const g=graph(),roots=g?.roots||[],keys=[...new Set(roots.map(r=>r.mapKey))];if(!keys.includes(state.mapKey))state.mapKey=keys[0]||null;const list=roots.filter(r=>r.mapKey===state.mapKey);if(!list.some(r=>r.id===state.rootId))state.rootId=list[0]?.id||null;const root=roots.find(r=>r.id===state.rootId);
  host.innerHTML=`<header class="story-header"><button id="nativeStoryExit" type="button">← Map editor</button><b>ROM story</b><button id="nativeStoryProject" type="button">Project cards</button><button id="nativeStorySystems" type="button">Shattered systems</button><button id="nativeStoryImport" type="button">Import entire ROM</button></header><div class="native-story-controls"><label>Map<select id="nativeStoryMap">${keys.map(k=>`<option value="${esc(k)}" ${k===state.mapKey?'selected':''}>${esc(roots.find(r=>r.mapKey===k).mapName)}</option>`).join('')}</select></label><label>Event / entry point<select id="nativeStoryRoot">${list.map(r=>`<option value="${esc(r.id)}" ${r.id===state.rootId?'selected':''}>${esc(r.title)}${r.previewAddress?' · '+esc((g.edits.texts[r.previewAddress]?.text??g.texts[r.previewAddress]?.text??'').replace(/\\[npl]/g,' ').slice(0,50)):''}</option>`).join('')}</select></label><label>View<select id="nativeStoryView"><option value="scene">Map and event steps</option><option value="steps">Event steps</option><option value="graph">Advanced command graph</option></select></label><input id="nativeStorySearch" type="search" placeholder="Find a command or dialogue"><span id="nativeStoryCounts">${g?.notices.some(n=>n.message.includes('limit reached'))?'Partial index · ':''}${roots.length} event entries · ${Object.keys(g?.nodes||{}).length} commands · ${nativeStoryEditCount(api.project(),session().id)} edits</span></div><div id="nativeStoryBoard" class="story-board" aria-label="Native ROM event graph"><div id="nativeStoryPlane" class="story-plane"><svg id="nativeStoryLinks" class="story-links"></svg><div id="nativeStoryCards"></div></div>${root?'':'<p class="story-empty">Import the ROM’s native event graph to see its story.</p>'}</div><footer class="story-footer"><span id="nativeStoryStatus"></span><button id="nativeStoryNotices" type="button">Notices</button><button id="nativeStoryMore" type="button">Show more</button><button id="nativeStoryFit" type="button">Fit</button><button id="nativeStoryArrange" type="button">Arrange event</button><button id="nativeStoryCondition" type="button">Entry condition</button><button id="nativeStoryMapOpen" type="button">Show event on map</button></footer>`;
  $('#nativeStoryView').value=state.view;$('#nativeStoryView').onchange=()=>{state.view=$('#nativeStoryView').value;renderGraph();fit();};$('#nativeStorySystems').hidden=!shatteredAdapter(session().reader);$('#nativeStorySystems').disabled=!g;$('#nativeStorySystems').onclick=()=>systems.open();$('#nativeStoryNotices').onclick=()=>{const unresolved=Object.values(g?.nodes||{}).filter(n=>n.opaque),external=Object.values(g?.nodes||{}).filter(n=>n.external).length;api.modal('ROM story coverage',`<p>${unresolved.length} unresolved command boundaries and ${external} native/shared engine routine calls. Verified Shattered standard scripts expand into the graph. Native routines remain references with typed data editors where verified; they are not expanded into C or assembly graphs.</p>${[...(g?.notices||[]),...unresolved.map(n=>({at:n.at,message:n.reason}))].slice(0,100).map(n=>`<p>${n.mapKey?esc(n.mapKey)+' · ':''}${n.at?h(n.at)+' · ':''}${esc(n.message)}</p>`).join('')}<p>First 100 notices shown. Unresolved command bytes remain unchanged.</p>`);};$('#nativeStoryArrange').disabled=!root;$('#nativeStoryArrange').onclick=()=>arrange();$('#nativeStoryCondition').disabled=root?.kind!=='map condition';$('#nativeStoryCondition').onclick=()=>editCondition(root);$('#nativeStoryExit').onclick=close;$('#nativeStoryProject').onclick=projectCards;$('#nativeStoryImport').onclick=()=>importEvents().catch(api.error);$('#nativeStoryMap').onchange=()=>{state.mapKey=$('#nativeStoryMap').value;state.limit=100;draw();};$('#nativeStoryRoot').onchange=()=>{state.rootId=$('#nativeStoryRoot').value;state.limit=100;draw();};$('#nativeStorySearch').oninput=renderGraph;$('#nativeStoryMore').onclick=()=>{state.limit+=100;renderGraph();};$('#nativeStoryFit').onclick=fit;$('#nativeStoryMapOpen').onclick=()=>{const m=api.project().maps.find(m=>m.rom?.sourceId===session().id&&m.rom.key===state.mapKey);if(!m){api.toast('Import this map into the project to edit its placement.');return;}const r=graph().roots.find(r=>r.id===state.rootId);state.active=false;host.hidden=true;const type={npcs:'npc',signs:'sign',triggers:'trigger'}[r?.kind],marker=m.markers.find(n=>n.rom?.type===type&&n.rom?.index===r?.index);api.openMap(m.id,marker||null);};
  const board=$('#nativeStoryBoard');board.onpointerdown=e=>{if(state.view!=='graph'||e.target.closest('button'))return;board.setPointerCapture?.(e.pointerId);drag={x:e.clientX,y:e.clientY,cx:cam.x,cy:cam.y};};board.onpointermove=e=>{if(!drag)return;cam.x=drag.cx+e.clientX-drag.x;cam.y=drag.cy+e.clientY-drag.y;transform();};board.onpointerup=board.onpointercancel=()=>drag=null;board.onwheel=e=>{if(state.view!=='graph')return;e.preventDefault();const r=board.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,scale=Math.max(.15,Math.min(1.5,cam.scale*(e.deltaY>0?.9:1.1)));cam.x=x-(x-cam.x)*scale/cam.scale;cam.y=y-(y-cam.y)*scale/cam.scale;cam.scale=scale;transform();};renderGraph();fit();
 }
 function transform(){if($('#nativeStoryPlane'))$('#nativeStoryPlane').style.transform=`translate(${cam.x}px,${cam.y}px) scale(${cam.scale})`;}
 function fit(){if(state.view!=='graph'){cam={x:0,y:0,scale:1};transform();return;}cam={x:20,y:20,scale:Math.min(.85,Math.max(.25,($('#nativeStoryBoard').clientWidth||700)/1100))};transform();}
 function renderGraph(){let g=graph(),root=g?.roots.find(r=>r.id===state.rootId);if(!root)return;if(g.edits.flows?.[root.id]){g=previewStoryFlow(g,root,g.edits.flows[root.id]);root=g.roots.find(r=>r.id===state.rootId);}const seen=[...reachableStory(g,root.address)],q=($('#nativeStorySearch').value||'').toLowerCase(),shown=seen.filter(at=>{const n=g.nodes[at];return!q||[n.name,readableStoryAction(g,n).title,readableStoryAction(g,n).detail,n.adapter?.name||'',h(at),...n.args?.filter(a=>a.kind==='text').map(a=>g.edits.texts[a.value-BASE]?.text??g.texts[a.value-BASE]?.text)||[]].join(' ').toLowerCase().includes(q);}).slice(0,state.limit),positions=new Map(shown.map((at,i)=>[at,{x:i%4*285,y:Math.floor(i/4)*205}]));
  if(state.view!=='graph'){renderSteps(g,shown,seen);if(state.view==='scene')mountSceneMap({host,api,graph:g,root,shown,session:session(),editMovement});return;}$('#nativeStoryBoard').classList.remove('readable-story','scene-story');
  $('#nativeStoryCards').innerHTML=shown.map(at=>{const n=g.nodes[at],p=positions.get(at),patch=g.edits.commands[at],args=n.args?.map((a,i)=>patch?.args[i]??a.value),dialog=n.args?.find(a=>a.kind==='text'),text=dialog&&(g.edits.texts[dialog.value-BASE]?.text??g.texts[dialog.value-BASE]?.text);return`<article class="story-card ${n.opaque?'needs-attention':''}" style="left:${p.x}px;top:${p.y}px"><small>${h(at)} ${patch?'· edited':''}</small><b>${esc(n.adapter?.name||n.name)}</b><p>${esc(n.opaque?n.reason:text||(n.external?'Native/shared engine routine · preserved. ':'')+args?.map(h).join(', ')||'No arguments')}</p><div><button type="button" data-native-command="${at}">${n.opaque?'Inspect':'Edit command'}</button>${n.args?.some(a=>a.kind==='text'&&g.texts[a.value-BASE])?`<button type="button" data-native-text="${at}">Dialogue</button>`:''}${n.args?.some(a=>a.kind==='movement'&&g.movements[a.value-BASE])?`<button type="button" data-native-movement="${at}">Movement</button>`:''}</div></article>`;}).join('');
  $('#nativeStoryLinks').innerHTML=shown.flatMap(at=>effectiveStoryEdges(g,g.nodes[at]).map(e=>{const a=positions.get(at),b=positions.get(e.to);if(!b)return'';return`<g><path d="M${a.x+240},${a.y+80} C${a.x+270},${a.y+80} ${b.x-30},${b.y+80} ${b.x},${b.y+80}"/><text x="${(a.x+b.x+240)/2}" y="${(a.y+b.y)/2+70}">${esc(e.kind)}</text></g>`;})).join('');
  for(const b of host.querySelectorAll('[data-native-command]'))b.onclick=()=>editCommand(+b.dataset.nativeCommand);for(const b of host.querySelectorAll('[data-native-text]'))b.onclick=()=>editText(+b.dataset.nativeText);for(const b of host.querySelectorAll('[data-native-movement]'))b.onclick=()=>editMovement(+b.dataset.nativeMovement);$('#nativeStoryStatus').textContent=shown.length+' shown / '+seen.length+' reachable · '+(g.notices.length+Object.values(g.nodes).filter(n=>n.opaque).length)+' unresolved notices';$('#nativeStoryMore').hidden=shown.length>=seen.length;transform();
 }
 function renderSteps(g,shown,seen){const names=new Map(seen.map((at,i)=>[at,'Step '+(i+1)]));$('#nativeStoryBoard').classList.remove('scene-story');$('#nativeStoryBoard').classList.add('readable-story');$('#nativeStoryLinks').innerHTML='';$('#nativeStoryCards').innerHTML='<p class="story-step-help">Choose an event, then follow Continue, branch and sub-event links. Numbers identify commands; branches can change their order. Every decoded command remains available here.</p>'+shown.map(at=>{const n=g.nodes[at],a=readableStoryAction(g,n),edges=effectiveStoryEdges(g,n),actions=`${n.args?.some(a=>a.kind==='text'&&g.texts[a.value-BASE])?`<button data-native-text="${at}" type="button">Edit dialogue</button>`:''}${n.args?.some(a=>a.kind==='movement'&&g.movements[a.value-BASE])?`<button data-native-movement="${at}" type="button">Edit movement</button>`:''}`;return`<article id="storyStep${at}" class="story-readable-step ${n.opaque?'needs-attention':''}"><small>${names.get(at)} ${g.edits.commands?.[at]?'· edited':''}</small><h3>${esc(a.title)}</h3><p class="story-readable-text">${esc(a.detail)}</p><div class="smart-actions">${actions}</div><nav aria-label="Next event steps">${edges.map(e=>`<button data-story-follow="${e.to}" type="button">${esc(e.kind.startsWith('condition')?'If '+e.kind.slice(10):e.kind==='otherwise'?'Otherwise':e.kind==='next'?([4,7,9,11].includes(n.code)?'After return':'Continue'):e.kind)} → ${esc(names.get(e.to)||h(e.to))}</button>`).join('')}</nav><details><summary>${a.technical?'Edit story value / advanced details':'Advanced details'}</summary><p>${esc(n.name)} · ${h(at)}</p><button data-native-command="${at}" type="button">${n.opaque?'Inspect':'Edit command'}</button></details></article>`;}).join('');for(const b of host.querySelectorAll('[data-native-command]'))b.onclick=()=>editCommand(+b.dataset.nativeCommand);for(const b of host.querySelectorAll('[data-native-text]'))b.onclick=()=>editText(+b.dataset.nativeText);for(const b of host.querySelectorAll('[data-native-movement]'))b.onclick=()=>editMovement(+b.dataset.nativeMovement);for(const b of host.querySelectorAll('[data-story-follow]'))b.onclick=()=>{const at=+b.dataset.storyFollow;if(!$('#storyStep'+at)){state.limit=seen.indexOf(at)+100;renderGraph();}$('#storyStep'+at)?.scrollIntoView?.({block:'center',behavior:'smooth'});};$('#nativeStoryStatus').textContent=shown.length+' steps shown · '+seen.length+' reachable';$('#nativeStoryMore').hidden=shown.length>=seen.length;cam={x:0,y:0,scale:1};transform();}
 function arrange(at=null){const g=graph(),root=g.roots.find(r=>r.id===state.rootId),flow=g.edits.flows?.[root.id],selected=flow&&at!==null?Object.values(previewStoryFlow(g,root,flow).nodes).find(n=>n.at===at)?.flowStep:null;openStoryFlow({api,graph:g,root,session:session(),afterSave:draw,selected});}
 function impact(at){const g=graph(),back=new Map();for(const n of Object.values(g.nodes))for(const e of effectiveStoryEdges(g,n)){if(!back.has(e.to))back.set(e.to,[]);back.get(e.to).push(n.at);}const seen=new Set(),queue=[at];while(queue.length){const n=queue.shift();if(seen.has(n))continue;seen.add(n);queue.push(...back.get(n)||[]);}const roots=g.roots.filter(r=>seen.has(r.address));return roots.length+' event entries across '+new Set(roots.map(r=>r.mapKey)).size+' maps can reach this command.';}
 function editCondition(root){const g=graph(),prior=g.edits.conditions?.[root.reference];api.modal('Map-entry condition',`<p>This table entry runs its script when the saved variable matches the value. Shared references use the same condition.</p><label>Variable<input id="nativeConditionVariable" value="${h(prior?.variable??root.variable)}"></label><label>Value<input id="nativeConditionValue" value="${h(prior?.value??root.value)}"></label><button id="nativeConditionReset" type="button">Restore source condition</button>`,()=>{const variable=parseStoryNumber($('#nativeConditionVariable').value,2),value=parseStoryNumber($('#nativeConditionValue').value,2);if(!variable)throw Error('Variable zero terminates the table. Choose a saved variable.');api.change(()=>{g.edits.conditions??={};g.edits.conditions[root.reference]={original:root.conditionOriginal,variable,value};});draw();},'Save condition');$('#nativeConditionReset').onclick=()=>{api.change(()=>{if(g.edits.conditions)delete g.edits.conditions[root.reference];});api.close();draw();};}
 function editCommand(at){if(at>=session().reader.size)return arrange(at);const g=graph(),n=g.nodes[at],p=g.edits.commands[at];if(n.opaque){api.modal('Unresolved event command',`<p>${esc(n.reason)} at ${h(at)}. Parsing stops here; the original bytes are retained.</p><code>${Array.from(session().reader.bytes.slice(at,at+16),n=>n.toString(16).padStart(2,'0')).join(' ')}</code>`);return;}
  const inputs=boundShatteredInputs(g,n);api.modal(n.adapter?.name||n.name,`<p>${n.adapter?esc(n.adapter.support)+' · '+esc(n.name)+'<br>':''}${esc(impact(at))} Changes affect the shared script.</p>${[6,7].includes(n.code)?'<p>Condition: 0 less, 1 equal, 2 greater, 3 less/equal, 4 greater/equal, 5 not equal.</p>':''}${inputs.map((a,i)=>`<label>${esc(a.name)} · variable ${h(a.variable)}${a.assignment===null?' · dynamic input':''}<input id="nativeBound${i}" type="number" min="${a.min}" max="${a.max}" ${a.assignment===null?'disabled':`value="${g.edits.commands[a.assignment]?.args[a.index]??g.nodes[a.assignment].args[a.index].value}"`}></label>`).join('')}${n.args.map((a,i)=>`<label>${esc(a.name)} · ${a.width*8} bits${a.kind==='script'?' · branch address':''}<input id="nativeArg${i}" value="${h(p?.args[i]??a.value)}" ${['text','movement','native'].includes(a.kind)||n.code===92&&i===0?'readonly':''}></label>`).join('')}<p>Branch targets use GBA addresses (0x08… / 0x09…). Dialogue and movement have their own editors.</p><button id="nativeCommandReset" type="button">Restore source command</button>`,()=>{const args=n.args.map((a,i)=>parseStoryNumber($('#nativeArg'+i).value,a.width));for(let i=0;i<n.args.length;i++)if(n.args[i].kind==='script'&&args[i]!==n.args[i].value&&(!g.nodes[args[i]-BASE]||g.nodes[args[i]-BASE].opaque))throw Error('Choose a decoded script address.');validateShatteredCallArgs(session().reader,n,args);const boundValues=inputs.map((a,i)=>{if(a.assignment===null)return null;const value=parseStoryNumber($('#nativeBound'+i).value,2);if(value<a.min||value>a.max)throw Error(a.name+' is outside the supported range.');return value;});api.change(()=>{for(let i=0;i<inputs.length;i++){const a=inputs[i];if(a.assignment===null)continue;const value=boundValues[i];const src=g.nodes[a.assignment],values=[...(g.edits.commands[a.assignment]?.args??src.args.map(a=>a.value))];values[a.index]=value;if(values.every((v,i)=>v===src.args[i].value))delete g.edits.commands[a.assignment];else g.edits.commands[a.assignment]={original:src.original,args:values};}if(args.every((a,i)=>a===n.args[i].value))delete g.edits.commands[at];else g.edits.commands[at]={original:n.original,args};});draw();},'Save command');$('#nativeCommandReset').onclick=()=>{api.change(()=>delete g.edits.commands[at]);api.close();draw();};
 }
 function editText(at){if(at>=session().reader.size)return arrange(at);const g=graph(),rows=graph().nodes[at].args.filter(a=>a.kind==='text'&&g.texts[a.value-BASE]).map(a=>g.texts[a.value-BASE]);api.modal('Event dialogue',`${rows.map((r,i)=>`<label>Text ${h(r.at)} · ${r.references.length} decoded references<textarea id="nativeText${i}" rows="5">${esc(g.edits.texts[r.at]?.text??r.text)}</textarea></label><div id="nativeTextPreview${i}" class="dialogue-preview"></div>`).join('')}<p>Use \\n for a line, \\l to scroll, and \\p for a new page. Shared text updates every decoded reference in this graph.</p><button id="nativeTextReset" type="button">Restore source dialogue</button>`,()=>{const patches=rows.map((r,i)=>{const text=$('#nativeText'+i).value;if(encodeStoryText(text).length>8192)throw Error('Dialogue is too long.');return{r,text};});api.change(()=>{for(const{r,text}of patches)if(text===r.text)delete g.edits.texts[r.at];else g.edits.texts[r.at]={original:r.original,text};});draw();},'Save dialogue');for(let i=0;i<rows.length;i++){const preview=()=>{$('#nativeTextPreview'+i).textContent=$('#nativeText'+i).value.replaceAll('\\n','\n').replaceAll('\\l','\n').replaceAll('\\p','\n\n');};$('#nativeText'+i).oninput=preview;preview();}$('#nativeTextReset').onclick=()=>{api.change(()=>{for(const r of rows)delete g.edits.texts[r.at];});api.close();draw();};}
 function editMovement(at){if(at>=session().reader.size)return arrange(at);const g=graph(),n=g.nodes[at],arg=n.args.find(a=>a.kind==='movement'&&g.movements[a.value-BASE]),r=g.movements[arg.value-BASE],names=movementNames(),byCode=new Map(names.map(m=>[m.code,m.name])),values=(g.edits.movements[r.at]?.bytes??r.bytes).slice(0,-1);let draft=[...values];
  api.modal('Event movement',`<p>${r.references.length} decoded references share this sequence. Actor ${h(g.edits.commands[at]?.args[0]??n.args[0].value)}.</p><div id="nativeMovementSteps"></div><div class="field-row"><select id="nativeMovementAdd">${names.filter(m=>m.code!==254).map(m=>`<option value="${m.code}">${esc(m.name)}</option>`).join('')}</select><button id="nativeMovementAppend" type="button">Add action</button></div><button id="nativeMovementDraw" type="button">Draw replacement route on map</button><div id="nativeMovementDrawing"></div><canvas id="nativeMovementPreview" width="320" height="240" style="max-width:100%;image-rendering:pixelated"></canvas><p id="nativeMovementPreviewInfo" class="small"></p><p>Preview shows stock walk/jump displacement; it does not simulate collisions, waits, native routines or custom action meanings.</p><button id="nativeMovementReset" type="button">Restore source movement</button>`,()=>{if(draft.length>511)throw Error('Use up to 511 movement actions.');api.change(()=>{const bytes=[...draft,254];if(JSON.stringify(bytes)===JSON.stringify(r.bytes))delete g.edits.movements[r.at];else g.edits.movements[r.at]={original:r.original,bytes};});draw();},'Save movement');
  const redraw=()=>{$('#nativeMovementSteps').innerHTML=draft.map((code,i)=>`<div class="field-row"><span>${i+1}. ${esc(byCode.get(code)||h(code))}</span><button type="button" data-native-move-up="${i}">↑</button><button type="button" data-native-move-delete="${i}">Remove</button></div>`).join('');for(const b of document.querySelectorAll('[data-native-move-delete]'))b.onclick=()=>{draft.splice(+b.dataset.nativeMoveDelete,1);redraw();};for(const b of document.querySelectorAll('[data-native-move-up]'))b.onclick=()=>{const i=+b.dataset.nativeMoveUp;if(i)[draft[i-1],draft[i]]=[draft[i],draft[i-1]];redraw();};previewMovement(draft,byCode,n);};$('#nativeMovementAppend').onclick=()=>{if(draft.length>=511)throw Error('Movement limit reached.');draft.push(+$('#nativeMovementAdd').value);redraw();};$('#nativeMovementReset').onclick=()=>{draft=r.bytes.slice(0,-1);redraw();};$('#nativeMovementDraw').onclick=()=>{$('#nativeMovementDrawing').replaceChildren(mountMovementPathEditor({api,graph:g,root:g.roots.find(r=>r.id===state.rootId),session:session(),node:n,onApply:bytes=>{draft=bytes;redraw();api.toast('Drawn route applied to this draft. Save movement to keep it.');}}));};redraw();
 }
 function previewMovement(bytes,names,node){const c=$('#nativeMovementPreview'),ctx=c.getContext('2d'),r=graph().roots.find(r=>r.id===state.rootId),map=session().reader.byKey(r.mapKey),actor=session().reader.events(map).npcs.find(n=>n.localId===(graph().edits.commands[node.at]?.args[0]??node.args[0].value));let x=actor?.x??r.x??Math.floor(map.layout.width/2),y=actor?.y??r.y??Math.floor(map.layout.height/2),path=[[x,y]],unknown=0;for(const b of bytes){const name=names.get(b)||'',m=/^(walk_(?!in_place)|jump_(?:2_|1_)?)(.*)(down|up|left|right)$/.exec(name);if(m&&!name.includes('in_place')){const step=name.startsWith('jump_2_')?2:1,d=m[3];x+=(d==='right'?step:d==='left'?-step:0);y+=(d==='down'?step:d==='up'?-step:0);path.push([x,y]);}else if(!/^(face|delay|walk_in_place|step_end)/.test(name))unknown++;}ctx.fillStyle='#eef2df';ctx.fillRect(0,0,320,240);const scale=16,ox=160-path[0][0]*scale,oy=120-path[0][1]*scale;try{const art=session().reader.render(map),canvas=document.createElement('canvas');canvas.width=art.width;canvas.height=art.height;const ac=canvas.getContext('2d'),d=ac.createImageData(art.width,art.height);d.data.set(art.pixels);ac.putImageData(d,0,0);ctx.drawImage(canvas,ox,oy);}catch{}ctx.strokeStyle='#e800a5';ctx.lineWidth=3;ctx.beginPath();path.forEach(([x,y],i)=>i?ctx.lineTo(ox+x*scale+8,oy+y*scale+8):ctx.moveTo(ox+x*scale+8,oy+y*scale+8));ctx.stroke();ctx.fillStyle='#8020b0';ctx.fillRect(ox+x*scale+3,oy+y*scale+3,10,10);$('#nativeMovementPreviewInfo').textContent='Start '+path[0].join(',')+' → '+[x,y].join(',')+(unknown?' · '+unknown+' actions have no path preview':'');}
 return{state,open,close,render:draw,importEvents};
}
